--
-- Table structure for table `t_product_review`
--

DROP TABLE IF EXISTS `t_product_review`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_product_review` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` bigint NOT NULL COMMENT '商品 ID',
  `user_id` bigint NOT NULL COMMENT '评价用户 ID',
  `order_id` bigint DEFAULT NULL COMMENT '关联订单 ID（仅已购买用户可评）',
  `rating` tinyint NOT NULL COMMENT '评分 1-5',
  `content` text NOT NULL COMMENT '评价内容',
  `is_anonymous` tinyint DEFAULT '0' COMMENT '是否匿名 1是 0否',
  `is_hidden` tinyint DEFAULT '0' COMMENT '是否隐藏 1是 0否（后台审核）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_user` (`user_id`),
  KEY `fk_rev_order` (`order_id`),
  CONSTRAINT `fk_rev_order` FOREIGN KEY (`order_id`) REFERENCES `t_order` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_rev_prod` FOREIGN KEY (`product_id`) REFERENCES `t_product` (`id`),
  CONSTRAINT `fk_rev_user` FOREIGN KEY (`user_id`) REFERENCES `t_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品评价表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `t_product_review`
--

LOCK TABLES `t_product_review` WRITE;
/*!40000 ALTER TABLE `t_product_review` DISABLE KEYS */;
INSERT INTO `t_product_review` VALUES (1,1,1,NULL,5,'原味瓜子颗粒饱满，越嚼越香，停不下来。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(2,2,1,NULL,5,'巴西松子很新鲜，手剥很解压。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(3,11,1,NULL,5,'牛肉干辣度刚好，纤维清晰，嚼劲十足。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(4,21,1,NULL,4,'冰镇绿豆糕真的绝配夏天！',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(5,31,1,NULL,5,'芒果干厚切，酸甜适中。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(6,41,2,NULL,5,'原味薯片吃一辈子都吃不腻。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(7,11,2,NULL,5,'已经回购第三次了，麦乐迪家牛肉干是天花板。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(8,2,2,NULL,5,'松子真的很香，老人小孩都爱吃。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(9,10,2,NULL,4,'每日坚果方便，搭配牛奶很好。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(10,51,2,NULL,5,'卫龙经典，童年回忆。',0,0,'2026-07-17 21:03:22','2026-07-17 21:03:22'),(11,43,4,NULL,5,'啊啊啊啊啊啊啊',0,0,'2026-07-22 14:23:46','2026-07-22 14:23:46'),(12,41,4,NULL,5,'非常的好吃，吃不腻',0,0,'2026-07-22 14:24:13','2026-07-22 14:24:13'),(13,44,4,NULL,1,'一般般，不好吃',0,0,'2026-07-22 14:29:03','2026-07-22 14:29:03'),(14,41,1,NULL,5,'非常的奈斯',0,0,'2026-07-22 14:37:09','2026-07-22 14:37:09'),(15,41,5,NULL,1,'口感一般，味道不好',0,0,'2026-07-27 14:53:28','2026-07-27 14:53:28'),(16,41,30,NULL,5,'好吃不贵健康实惠',0,0,'2026-08-03 19:15:42','2026-08-03 19:15:42');
/*!40000 ALTER TABLE `t_product_review` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `t_product_sku`
--

DROP TABLE IF EXISTS `t_product_sku`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `t_product_sku` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键（PRD §6.1.1 字段 sku_id 改名 id 统一规范）',
  `product_id` bigint NOT NULL COMMENT '所属商品 ID',
  `spec_name` varchar(64) NOT NULL COMMENT '规格名（如"麻辣味/60g"）',
  `sku_code` varchar(32) DEFAULT NULL COMMENT 'SKU 编码',
  `price` decimal(10,2) NOT NULL COMMENT '该 SKU 的售价',
  `stock` int NOT NULL DEFAULT '0' COMMENT '该 SKU 的库存',
  `image` varchar(255) DEFAULT NULL COMMENT '该 SKU 对应图片（默认沿用商品主图）',
  `sales` int DEFAULT '0' COMMENT '该 SKU 销量（冗余字段，便于排序）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '上下架状态 0下架 1上架',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_product` (`product_id`),
  CONSTRAINT `fk_sku_prod` FOREIGN KEY (`product_id`) REFERENCES `t_product` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=167 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品规格/SKU 表（PRD §6.1.1 V1.1 补充）';
/*!40101 SET character_set_client = @saved_cs_client */;

